const payload = $input.first().json || {};
const body = payload.body || {};
const headers = payload.headers || {};
const sharedSecret = $env.ASTOREKA_WEBHOOK_SECRET || '';
const receivedSecret = headers['x-astoreka-webhook-secret'] || headers['X-Astoreka-Webhook-Secret'] || '';
const eventId = headers['x-astoreka-event-id'] || headers['X-Astoreka-Event-Id'] || body.id || '';

if (!sharedSecret) {
  return [{ json: { ok: false, statusCode: 503, error: 'missing_shared_secret', message: 'Configura ASTOREKA_WEBHOOK_SECRET en n8n antes de activar este workflow.' } }];
}

if (receivedSecret !== sharedSecret) {
  return [{ json: { ok: false, statusCode: 401, error: 'invalid_shared_secret', message: 'Secreto no valido.' } }];
}

const eventType = body.type || 'unknown';
const job = body.job || {};
const clients = body.appData?.clients || [];
const assets = body.appData?.assets || [];
const invoices = body.appData?.invoices || [];
const estimates = body.appData?.estimates || [];
const client = clients.find(item => item.id === job.clientId) || null;
const asset = assets.find(item => item.id === job.assetId) || null;
const invoice = invoices.find(item => item.jobId === job.id) || null;
const estimate = estimates.find(item => item.jobId === job.id) || null;
const nextAction = {
  job_created: 'Registrar aviso y avisar a oficina si es urgente',
  estimate_created: 'Enviar presupuesto al cliente y programar seguimiento',
  job_status_changed: 'Registrar cambio de estado en historial externo',
  invoice_created: 'Programar seguimiento de cobro',
  invoice_collected: 'Cerrar cobro y actualizar resumen diario'
}[eventType] || 'Revisar evento manualmente';
return [{ json: { ok: true, statusCode: 200, eventId, eventType, receivedAt: new Date().toISOString(), job: { id: job.id, code: job.code, status: job.status, priority: job.priority, symptoms: job.symptoms, total: job.totals?.total || 0 }, client, asset, invoice, estimate, nextAction } }];
